/* Ideas and issues: optional image, private receiver-only inbox. */
(()=>{'use strict';if(!document.body.classList.contains('shared-app'))return;const q=s=>document.querySelector(s);let receiver=false,checkedUser='',checking=false;
const icon='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M8 14.5a6 6 0 1 1 8 0c-1 .8-1.5 1.5-1.5 2.5h-5c0-1-.5-1.7-1.5-2.5Z"/><path d="M9.5 20h5M11 23h2M12 1v1M3 5l1 1M21 5l-1 1"/></svg>';
function frame(){selectedTask=null;modal(modalHead('یه فکری دارم')+'<div class="idea-tabs">'+(receiver?'<button type="button" data-idea-tab="compose">نوشتن پیام</button><button type="button" data-idea-tab="inbox">پیام‌های دریافتی</button>':'')+'</div><div id="ideaBody"></div>');q('#sharedDialog').classList.add('idea-dialog');q('#sharedDialog').addEventListener('close',()=>q('#sharedDialog').classList.remove('idea-dialog'),{once:true});q('[data-idea-tab=compose]')?.addEventListener('click',compose);q('[data-idea-tab=inbox]')?.addEventListener('click',inbox)}
function active(mode){document.querySelectorAll('[data-idea-tab]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.ideaTab===mode)))}
function compose(){active('compose');q('#ideaBody').innerHTML='<p class="idea-intro">یه ایده، یه ایراد یا یه «کاش می‌شد…»؟ اینجا برامون بنویس.</p><form id="ideaForm"><label>چی تو فکرته؟<textarea name="body" required maxlength="4000" rows="5" placeholder="ایده‌ت رو بگو یا توضیح بده کجا به مشکل خوردی…"></textarea></label><label class="idea-attachment">عکس از مشکل <small>اختیاری · تا ۵ مگابایت · می‌تونی عکس رو همین‌جا پیست کنی (Ctrl+V)</small><input type="file" name="image" accept="image/png,image/jpeg,image/webp"></label><img class="idea-preview" hidden alt="پیش‌نمایش عکس انتخاب‌شده"><button type="button" class="text-btn idea-remove-image" hidden>حذف عکس</button><p class="idea-error" role="alert" hidden></p><button class="primary" type="submit">بفرستش 💡</button></form>';const form=q('#ideaForm'),file=form.elements.image,preview=form.querySelector('img'),error=form.querySelector('.idea-error');let previewUrl='',uploadedPath='',uploadedFile=null,selectedImage=null;const remove=form.querySelector('.idea-remove-image');const fail=text=>{error.hidden=false;error.textContent=text};function selectImage(f){error.hidden=true;if(f&&(!['image/png','image/jpeg','image/webp'].includes(f.type)||f.size>5242880||!f.size)){file.value='';return fail('یک عکس PNG، JPG یا WebP تا ۵ مگابایت انتخاب کن.')}if(previewUrl)URL.revokeObjectURL(previewUrl);previewUrl='';preview.hidden=true;selectedImage=f||null;remove.hidden=!selectedImage;if(f){previewUrl=URL.createObjectURL(f);preview.src=previewUrl;preview.hidden=false}}file.onchange=()=>selectImage(file.files[0]);remove.onclick=()=>{file.value='';selectImage(null)};const pasteImage=e=>{if(!form.isConnected||!q('#sharedDialog').open)return;const item=[...(e.clipboardData?.items||[])].find(x=>x.kind==='file'&&x.type.startsWith('image/'));const image=item?.getAsFile();if(!image)return;e.preventDefault();file.value='';selectImage(image)};q('#sharedDialog').addEventListener('paste',pasteImage);q('#sharedDialog').addEventListener('close',()=>q('#sharedDialog').removeEventListener('paste',pasteImage),{once:true});q('#sharedDialog').addEventListener('close',()=>{if(previewUrl)URL.revokeObjectURL(previewUrl)},{once:true});form.onsubmit=async e=>{e.preventDefault();error.hidden=true;const text=form.elements.body.value.trim();if(!text)return fail('یک توضیح کوتاه بنویس.');const b=form.querySelector('button[type=submit]');b.disabled=true;b.textContent='در حال ارسال…';try{const f=selectedImage;let path=null;if(f){if(!['image/png','image/jpeg','image/webp'].includes(f.type)||f.size>5242880||!f.size)throw Error('عکس باید تا ۵ مگابایت باشد.');if(uploadedFile!==f){const ext={'image/jpeg':'jpg','image/png':'png','image/webp':'webp'}[f.type];uploadedPath=session.user.id+'/'+crypto.randomUUID()+'.'+ext;await checked(db.storage.from('samandis-feedback').upload(uploadedPath,f,{contentType:f.type,upsert:false}));uploadedFile=f}path=uploadedPath}await rpc('sm_send_feedback',{p_body:text,p_image:path});if(previewUrl)URL.revokeObjectURL(previewUrl);q('#ideaBody').innerHTML='<div class="idea-success"><span>💡</span><h3>فکرت به دستمون رسید!</h3><p>مرسی که کمک می‌کنی اینجا بهتر بشه.</p><button type="button" class="secondary" id="ideaAgain">یه فکر دیگه</button></div>';q('#ideaAgain').onclick=compose;await badge()}catch(e){fail(failure(e));b.disabled=false;b.textContent='بفرستش 💡'}}}
async function inbox(){if(!receiver)return;active('inbox');const root=q('#ideaBody');root.innerHTML='<p class="shared-meta">در حال دریافت پیام‌ها…</p>';try{const rows=await checked(db.from('sm_feedback').select('*').order('created_at',{ascending:false}).limit(50));if(!root.isConnected)return;root.innerHTML=rows.length?'<div class="idea-inbox">'+rows.map(r=>'<article class="idea-message '+(!r.read?'unread':'')+'"><header><b>'+esc(r.sender_name)+'</b><small>'+esc(date(r.created_at))+'</small></header><p>'+esc(r.body)+'</p>'+(r.image_path?'<button type="button" class="secondary" data-idea-image="'+r.id+'">مشاهده عکس</button>':'')+(!r.read?'<button type="button" class="text-btn" data-idea-read="'+r.id+'">خواندم</button>':'')+'</article>').join('')+'</div>':'<p class="shared-meta">هنوز پیامی نرسیده.</p>';root.querySelectorAll('[data-idea-read]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{await checked(db.from('sm_feedback').update({read:true}).eq('id',b.dataset.ideaRead));await inbox();await badge()}catch(e){message(failure(e));b.disabled=false}});root.querySelectorAll('[data-idea-image]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{const row=rows.find(r=>r.id===b.dataset.ideaImage);const data=await checked(db.storage.from('samandis-feedback').createSignedUrl(row.image_path,120));const img=document.createElement('img');img.src=data.signedUrl;img.alt='عکس پیوست پیام';img.className='idea-inbox-image';b.replaceWith(img)}catch(e){message(failure(e));b.disabled=false}})}catch(e){root.textContent=failure(e)}}
async function badge(){const b=q('#ideaButton');if(!b||!receiver)return;try{const r=await db.from('sm_feedback').select('id',{count:'exact',head:true}).eq('read',false);if(r.error)throw r.error;b.classList.toggle('has-ideas',!!r.count);b.setAttribute('aria-label',r.count?'یه فکری دارم؛ پیام جدید':'یه فکری دارم')}catch{}}
function sync(){const bottom=q('.desk-bottom');if(!bottom)return;let button=q('#ideaButton');if(!button){button=document.createElement('button');button.id='ideaButton';button.type='button';button.className='idea-button';button.title='یه فکری دارم';button.setAttribute('aria-label','یه فکری دارم');button.innerHTML=icon;button.onclick=async()=>{if(!mine())return;if(checking)return;frame();receiver?inbox():compose()};bottom.insertBefore(button,q('.account-notifications')||q('.account-more'))}const uid=session?.user.id||'';button.hidden=!mine();if(uid!==checkedUser&&!checking){checkedUser=uid;receiver=false;if(uid){checking=true;rpc('sm_feedback_access').then(v=>{if(session?.user.id===uid){receiver=!!v;badge()}}).catch(()=>{}).finally(()=>checking=false)}}}
const old=render;render=function(...args){const r=old(...args);sync();return r};document.addEventListener('samandis-preferences-loaded',sync);setInterval(()=>{sync();badge()},60000);sync();
})();
